    const errorStatuses = ['FAILED', 'CANCELED', 'EXPIRED']
    if (errorStatuses.includes(operation.status)) {
      await renderBulkOperationResult(operation, outputFile)
    } else {
      renderSuccess({
        headline: 'Bulk operation is running.',
